private boolean isInContext(FMFile f) {
    String path = f.getFile().getAbsolutePath();
    for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
        if (contextFile.getFile().getAbsolutePath().equals(path)) {
            return true;
        }
