private void removeFromContext(FMFile f) {
    String path = f.getFile().getAbsolutePath();
    // Removing through the iterator instead of the list itself, as removing
    // directly from the list while iterating it throws a
    // ConcurrentModificationException.
    Iterator<FMFile> iterator = activity.getFileOpContext().getSecond().iterator();
    while (iterator.hasNext()) {
        FMFile contextFile = iterator.next();
        if (contextFile.getFile().getAbsolutePath().equals(path)) {
            iterator.remove();
        }
    }
}

